use crate::codec::bulk;
use crate::core::error::{RdpProtocolError, RdpResult};

const HISTORY_BUFFER_SIZE: usize = 65536;
const HISTORY_END_OFFSET: usize = 65535;
const PACKET_AT_FRONT_WINDOW: usize = 32768;

pub struct NcrushContext {
    history: Vec<u8>,
    offset: usize,
    offset_cache: [u32; 4],
}

impl Default for NcrushContext {
    fn default() -> Self {
        Self { history: vec![0u8; HISTORY_BUFFER_SIZE], offset: 0, offset_cache: [0; 4] }
    }
}

pub fn decompress(context: &mut NcrushContext, source: &[u8], flags: u8) -> RdpResult<Vec<u8>> {
    if flags & bulk::PACKET_AT_FRONT != 0 {
        if context.offset <= PACKET_AT_FRONT_WINDOW {
            return Err(RdpProtocolError::protocol(format!("ncrush PACKET_AT_FRONT insufficient history: offset={} (-1002)", context.offset)));
        }
        context.history.copy_within(context.offset - PACKET_AT_FRONT_WINDOW..context.offset, 0);
        context.offset = PACKET_AT_FRONT_WINDOW;
        context.history[PACKET_AT_FRONT_WINDOW..].fill(0);
    }
    if flags & bulk::PACKET_FLUSHED != 0 {
        context.offset = 0;
        context.history.fill(0);
        context.offset_cache = [0; 4];
    }
    if flags & bulk::PACKET_COMPRESSED == 0 {
        return Ok(source.to_vec());
    }
    if source.len() < 4 {
        return Err(RdpProtocolError::underrun(format!("ncrush input shorter than 4 bytes: {}", source.len())));
    }
    let mut src = 4usize;
    let mut nbits: i32 = 32;
    let mut bits = u32::from_le_bytes([source[0], source[1], source[2], source[3]]);
    let start = context.offset;
    let mut index_lec: u32;
    loop {
        loop {
            let mask = mask_at(29)?;
            let masked = bits & u32::from(mask);
            if masked as usize >= HUFF_TABLE_LEC.len() {
                return Err(RdpProtocolError::protocol(format!("ncrush LEC index out of range: {}", masked)));
            }
            let entry = HUFF_TABLE_LEC[masked as usize];
            index_lec = u32::from(entry & 0x0FFF);
            let bit_length = u32::from(entry >> 12);
            bits >>= bit_length;
            nbits -= bit_length as i32;
            fetch_bits(source, &mut src, &mut nbits, &mut bits)?;
            if index_lec >= 256 {
                break;
            }
            if context.offset >= HISTORY_END_OFFSET {
                return Err(RdpProtocolError::protocol("ncrush HistoryPtr out of bounds (-1003)".to_string()));
            }
            context.history[context.offset] = (entry & 0xFF) as u8;
            context.offset += 1;
        }
        if index_lec == 256 {
            break;
        }
        let copy_offset_index = index_lec.wrapping_sub(257);
        let length_of_match_base = if copy_offset_index >= 32 {
            let offset_cache_index = index_lec.wrapping_sub(289) as usize;
            if offset_cache_index >= 4 {
                return Err(RdpProtocolError::protocol(format!("ncrush OffsetCache index out of range: {} (-1004)", offset_cache_index)));
            }
            let copy_offset = context.offset_cache[offset_cache_index];
            let length_of_match = decode_lom(&mut bits, &mut nbits, source, &mut src)?;
            let old = context.offset_cache[offset_cache_index];
            context.offset_cache[offset_cache_index] = context.offset_cache[0];
            context.offset_cache[0] = old;
            copy_match(&mut context.history, &mut context.offset, copy_offset as usize, length_of_match)?;
            length_of_match
        } else {
            let copy_offset_bits = COPY_OFFSET_BITS_LUT[copy_offset_index as usize];
            let copy_offset_base = COPY_OFFSET_BASE_LUT[copy_offset_index as usize];
            let mut copy_offset = copy_offset_base.wrapping_sub(1);
            if copy_offset_bits != 0 {
                let idx = (2 * copy_offset_bits + 3) as usize;
                let mask = mask_at(idx)?;
                let masked = bits & u32::from(mask);
                let tmp = copy_offset_base.wrapping_add(masked);
                if tmp < 1 {
                    return Err(RdpProtocolError::protocol(format!("ncrush invalid CopyOffset: {}", tmp)));
                }
                copy_offset = tmp - 1;
                bits >>= copy_offset_bits;
                nbits -= copy_offset_bits as i32;
                fetch_bits(source, &mut src, &mut nbits, &mut bits)?;
            }
            let length_of_match = decode_lom(&mut bits, &mut nbits, source, &mut src)?;
            context.offset_cache[3] = context.offset_cache[2];
            context.offset_cache[2] = context.offset_cache[1];
            context.offset_cache[1] = context.offset_cache[0];
            context.offset_cache[0] = copy_offset;
            copy_match(&mut context.history, &mut context.offset, copy_offset as usize, length_of_match)?;
            length_of_match
        };
        if length_of_match_base == 2 {
            continue;
        }
    }
    if index_lec != 256 {
        return Err(RdpProtocolError::protocol(format!("ncrush EOS not reached: IndexLEC={}", index_lec)));
    }
    Ok(context.history[start..context.offset].to_vec())
}

fn decode_lom(bits: &mut u32, nbits: &mut i32, source: &[u8], src: &mut usize) -> RdpResult<usize> {
    let mask = mask_at(21)?;
    let masked = *bits & u32::from(mask);
    if masked as usize >= HUFF_TABLE_LOM.len() {
        return Err(RdpProtocolError::protocol(format!("ncrush LOM index out of range: {}", masked)));
    }
    let entry = HUFF_TABLE_LOM[masked as usize];
    let length_of_match = usize::from(entry & 0x0FFF);
    let bit_length = u32::from(entry >> 12);
    *bits >>= bit_length;
    *nbits -= bit_length as i32;
    fetch_bits(source, src, nbits, bits)?;
    if length_of_match >= LOM_BITS_LUT.len() {
        return Err(RdpProtocolError::protocol(format!("ncrush LOM extra bits index out of range: {}", length_of_match)));
    }
    let length_of_match_bits = LOM_BITS_LUT[length_of_match];
    let mut length_of_match_base = LOM_BASE_LUT[length_of_match];
    if length_of_match_bits != 0 {
        let idx = (2 * length_of_match_bits + 3) as usize;
        let extra_mask = mask_at(idx)?;
        let extra = *bits & u32::from(extra_mask);
        *bits >>= length_of_match_bits;
        *nbits -= length_of_match_bits as i32;
        length_of_match_base += extra;
        fetch_bits(source, src, nbits, bits)?;
    }
    Ok(length_of_match_base as usize)
}

fn copy_match(history: &mut [u8], history_ptr: &mut usize, copy_offset: usize, length_of_match: usize) -> RdpResult<()> {
    if length_of_match < 2 {
        return Err(RdpProtocolError::protocol("ncrush LengthOfMatch < 2 (-1005)".to_string()));
    }
    if *history_ptr >= HISTORY_END_OFFSET || length_of_match > HISTORY_END_OFFSET - *history_ptr {
        return Err(RdpProtocolError::protocol("ncrush match write out of bounds (-1006)".to_string()));
    }
    let mut copy_length = if length_of_match > copy_offset { copy_offset } else { length_of_match };
    if *history_ptr >= copy_offset {
        let mut src = *history_ptr - copy_offset;
        while copy_length > 0 {
            history[*history_ptr] = history[src];
            *history_ptr += 1;
            src += 1;
            copy_length -= 1;
        }
        let mut index = 0usize;
        let mut remaining = length_of_match;
        while remaining > copy_offset {
            if index >= copy_offset {
                index = 0;
            }
            history[*history_ptr] = history[src + index];
            *history_ptr += 1;
            index += 1;
            remaining -= 1;
        }
    } else {
        let mut src = HISTORY_END_OFFSET - (copy_offset - *history_ptr) + 1;
        while copy_length > 0 && src <= HISTORY_END_OFFSET {
            history[*history_ptr] = history[src];
            *history_ptr += 1;
            src += 1;
            copy_length -= 1;
        }
        src = 0;
        let mut index = 0usize;
        let mut remaining = length_of_match;
        while remaining > copy_offset {
            if index >= copy_offset {
                index = 0;
            }
            history[*history_ptr] = history[src + index];
            *history_ptr += 1;
            index += 1;
            remaining -= 1;
        }
    }
    Ok(())
}

fn fetch_bits(source: &[u8], src: &mut usize, nbits: &mut i32, bits: &mut u32) -> RdpResult<()> {
    if *nbits >= 16 {
        return Ok(());
    }
    if *src + 1 >= source.len() {
        if *src >= source.len() {
            if *nbits < 0 {
                return Err(RdpProtocolError::underrun("ncrush failed to fetch bits".to_string()));
            }
            return Ok(());
        }
        let value = u32::from(source[*src]);
        *src += 1;
        *bits = bits.wrapping_add(value.wrapping_shl(*nbits as u32));
        *nbits += 8;
        return Ok(());
    }
    let tmp = u32::from(source[*src]) | (u32::from(source[*src + 1]) << 8);
    *src += 2;
    *bits = bits.wrapping_add(tmp.wrapping_shl(*nbits as u32));
    *nbits += 16;
    Ok(())
}

fn mask_at(index: usize) -> RdpResult<u16> {
    if index + 1 >= HUFF_TABLE_MASK.len() {
        return Err(RdpProtocolError::protocol(format!("ncrush HuffTableMask out of range: {}", index)));
    }
    Ok(u16::from_le_bytes([HUFF_TABLE_MASK[index], HUFF_TABLE_MASK[index + 1]]))
}

